(() => {
  const links = [...document.querySelectorAll('[data-testid="titleLink"]')];
  return links.slice(0,10).map((a, i) => {
    let el = a;
    for (let j=0; j<8 && el; j++, el=el.parentElement) {
      const txt = el.innerText || '';
      if (/\b\d\.\d\b/.test(txt) || /Scored|Rated|Very Good|Wonderful|Excellent/.test(txt)) {
        return {i, title: a.innerText.trim(), containerLevel:j, text: txt.trim().slice(0,2000)};
      }
    }
    return {i, title: a.innerText.trim(), text: a.closest('div')?.innerText?.trim().slice(0,1000)};
  });
})()
